**Stack Implementation in TypeScript**
=====================================

A stack is a linear data structure that follows the Last-In-First-Out (LIFO) principle, meaning the last element added to the stack will be the first one to be removed.

**Stack Class**
---------------

```typescript
class Stack<T> {
  private elements: T[];

  constructor() {
    this.elements = [];
  }

  /**
   * Pushes an element onto the stack.
   * @param element The element to push onto the stack.
   */
  push(element: T): void {
    this.elements.push(element);
  }

  /**
   * Removes and returns the top element from the stack.
   * @returns The top element from the stack, or undefined if the stack is empty.
   */
  pop(): T | undefined {
    if (this.isEmpty()) {
      return undefined;
    }
    return this.elements.pop()!;
  }

  /**
   * Returns the top element from the stack without removing it.
   * @returns The top element from the stack, or undefined if the stack is empty.
   */
  peek(): T | undefined {
    if (this.isEmpty()) {
      return undefined;
    }
    return this.elements[this.elements.length - 1];
  }

  /**
   * Checks if the stack is empty.
   * @returns True if the stack is empty, false otherwise.
   */
  isEmpty(): boolean {
    return this.elements.length === 0;
  }

  /**
   * Returns the size of the stack.
   * @returns The number of elements in the stack.
   */
  size(): number {
    return this.elements.length;
  }

  /**
   * Returns a string representation of the stack.
   * @returns A string representation of the stack.
   */
  toString(): string {
    return `Stack(${this.elements.join(', ')})`;
  }
}
```

